 * @param {ListNode} list2
 * @return {ListNode}
 */
var mergeInBetween = function(list1, a, b, list2) {
    let curr = list1;
    for (let i = 0; i < a - 1; ++i) {
        curr = curr.next;
    }
    const nodeBeforeA = curr;
    for (let i = 0; i < b - a + 2; ++i) {
        curr = curr.next;
    }
    const nodeAfterB = curr;
    nodeBeforeA.next = list2;
    let tail2 = list2;
    while (tail2.next) {
        tail2 = tail2.next;
    }
    tail2.next = nodeAfterB;
    return list1;
};
